1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { SupabaseService } from '../supabase/supabase.service';
3	
4	// e-mail/phone entram direto num filtro .or() do PostgREST — sem validar formato,
5	// um valor com vírgula/parênteses injeta cláusulas extras no filtro (ex. ",id.gt.0").
6	export const EMAIL_RE = /^[^\s,()]+@[^\s,()]+\.[^\s,()]+$/;
7	export const PHONE_RE = /^\+?[0-9]{8,15}$/;
8	
9	export interface CompletarCadastroMotoboyBody {
10	  name: string;
11	  phone: string;
12	  foto_perfil: string;
13	  documento_frente: string;
14	  documento_verso?: string;
15	  comprovante_endereco: string;
16	}
17	
18	const BUCKET = 'motoboy-documentos';
19	
20	@Injectable()
21	export class MotoboyAuthService {
22	  constructor(private supabase: SupabaseService) {}
23	
24	  // Bucket privado — grava o path do objeto, não a URL (URL é gerada sob demanda via signed URL).
25	  private async uploadDocumento(motoboyId: number, campo: string, base64: string): Promise<string> {
26	    const matches = base64.match(/^data:([\w/+-]+);base64,(.+)$/);
27	    const mimeType = matches ? matches[1] : 'image/jpeg';
28	    const raw = matches ? matches[2] : base64;
29	    const buffer = Buffer.from(raw, 'base64');
30	    const ext = mimeType === 'application/pdf' ? 'pdf' : mimeType === 'image/png' ? 'png' : 'jpg';
31	    const path = `${motoboyId}/${campo}-${Date.now()}.${ext}`;
32	
33	    const { error } = await this.supabase.client.storage
34	      .from(BUCKET)
35	      .upload(path, buffer, { contentType: mimeType, upsert: true });
36	    if (error) throw error;
37	
38	    return path;
39	  }
40	
41	  // Chamado logo após o frontend criar a conta via supabase.auth.signUp() —
42	  // completa o cadastro do motoboy (docs, telefone) vinculado a essa conta real.
43	  // E-mail vem de user_profiles (populado pelo trigger handle_new_user no signUp),
44	  // não do body, pra não poder ser forjado.
45	  async completarCadastro(userId: string, body: CompletarCadastroMotoboyBody) {
46	    // Motoboy e dono de estabelecimento precisam ser contas separadas — regra
47	    // espelhada em OnboardingController.registrarInicial.
48	    const { data: restauranteVinculado } = await this.supabase.client
49	      .from('restaurants')
50	      .select('id')
51	      .eq('user_id', userId)
52	      .maybeSingle();
53	    if (restauranteVinculado) {
54	      throw new ForbiddenException('Esta conta já é de um estabelecimento. Cadastre-se como motoboy usando outra conta.');
55	    }
56	
57	    // Idempotente — reload/retry depois de já ter completado não deve duplicar.
58	    const { data: existente } = await this.supabase.client
59	      .from('motoboys')
60	      .select('id')
61	      .eq('user_id', userId)
62	      .maybeSingle();
63	    if (existente) throw new ConflictException('Cadastro de motoboy já concluído para esta conta.');
64	
65	    const { data: perfil } = await this.supabase.client
66	      .from('user_profiles')
67	      .select('email')
68	      .eq('id', userId)
69	      .maybeSingle();
70	    if (!perfil?.email) throw new NotFoundException('Conta não encontrada.');
71	
72	    if (!body.name?.trim()) throw new BadRequestException('Informe o nome');
73	    if (body.phone && !PHONE_RE.test(body.phone)) throw new BadRequestException('Telefone inválido');
74	
75	    const { data: motoboy, error } = await this.supabase.client
76	      .from('motoboys')
77	      .insert({
78	        user_id: userId,
79	        name: body.name.trim(),
80	        phone: body.phone || null,
81	        email: perfil.email,
82	        precisa_completar_cadastro: false,
83	        status_plataforma: 'pendente',
84	      })
85	      .select('id')
86	      .single();
87	    if (error) throw error;
88	
89	    const [foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url] = await Promise.all([
90	      this.uploadDocumento(motoboy.id, 'foto-perfil', body.foto_perfil),
91	      this.uploadDocumento(motoboy.id, 'documento-frente', body.documento_frente),
92	      body.documento_verso ? this.uploadDocumento(motoboy.id, 'documento-verso', body.documento_verso) : Promise.resolve(null),
93	      this.uploadDocumento(motoboy.id, 'comprovante-endereco', body.comprovante_endereco),
94	    ]);
95	
96	    await this.supabase.client
97	      .from('motoboys')
98	      .update({ foto_perfil_url, documento_frente_url, documento_verso_url, comprovante_endereco_url })
99	      .eq('id', motoboy.id);
100	
101	    await this.supabase.client
102	      .from('user_profiles')
103	      .update({ role: 'motoboy', updated_at: new Date().toISOString() })
104	      .eq('id', userId);
105	
106	    return { ok: true };
107	  }
108	}
