1	import { Injectable, Logger } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import * as crypto from 'crypto';
4	
5	export interface Coordenadas {
6	  lat: number;
7	  lng: number;
8	}
9	
10	export interface ResultadoGeocodificacao {
11	  lat: number | null;
12	  lng: number | null;
13	  // null quando a geocodificação falhou — o chamador NÃO deve persistir esse hash
14	  // (deixa o hash salvo desatualizado de propósito, pra tentar de novo no próximo
15	  // save mesmo com o endereço idêntico, em vez de "travar" num resultado nulo).
16	  hash: string | null;
17	}
18	
19	// Nominatim (OpenStreetMap) é gratuito mas rate-limited (~1 req/s) — throttle simples em memória.
20	@Injectable()
21	export class GeocodingService {
22	  private readonly logger = new Logger(GeocodingService.name);
23	  private ultimaChamada = 0;
24	  private readonly intervaloMinMs = 1100;
25	
26	  constructor(private config: ConfigService) {}
27	
28	  private async aguardarRateLimit() {
29	    const agora = Date.now();
30	    const espera = this.ultimaChamada + this.intervaloMinMs - agora;
31	    if (espera > 0) await new Promise((r) => setTimeout(r, espera));
32	    this.ultimaChamada = Date.now();
33	  }
34	
35	  async geocodeEndereco(texto: string): Promise<Coordenadas | null> {
36	    if (!texto?.trim()) return null;
37	
38	    try {
39	      await this.aguardarRateLimit();
40	
41	      const userAgent = this.config.get('NOMINATIM_USER_AGENT') ?? 'DeliveryHub/1.0';
42	      const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(texto)}&format=json&limit=1`;
43	      const res = await fetch(url, { headers: { 'User-Agent': userAgent } });
44	      if (!res.ok) return null;
45	
46	      const results = (await res.json()) as Array<{ lat: string; lon: string }>;
47	      if (!results?.length) return null;
48	
49	      return { lat: parseFloat(results[0].lat), lng: parseFloat(results[0].lon) };
50	    } catch (e) {
51	      this.logger.warn(`Falha ao geocodificar "${texto}": ${(e as Error).message}`);
52	      return null;
53	    }
54	  }
55	
56	  // Endereço brasileiro completo (rua + número + bairro + CEP) costuma dar ZERO
57	  // resultado no Nominatim — numeração residencial e nomes de bairro com variações
58	  // (ex: "Vila (Mosqueiro)") raramente batem com o dado do OpenStreetMap. Tenta do
59	  // mais específico pro mais genérico, e usa o primeiro que encontrar algo — melhor
60	  // aproximar pela rua do que não geocodificar nada.
61	  private construirQueriesBr(addressJson: Record<string, string>): string[] {
62	    const { logradouro, numero, bairro, cidade, estado, cep } = addressJson;
63	    const candidatos = [
64	      [logradouro, numero, bairro, cidade, estado, cep],
65	      [logradouro, numero, cidade, estado],
66	      [logradouro, bairro, cidade, estado],
67	      [logradouro, cidade, estado],
68	    ].map((partes) => partes.filter(Boolean).join(', '));
69	
70	    return [...new Set(candidatos.filter(Boolean))];
71	  }
72	
73	  async geocodeEnderecoBr(addressJson: Record<string, string> | null | undefined): Promise<Coordenadas | null> {
