281	    setProcessando(true);
282	    try {
283	      await aceitarSolicitacaoMotoboy(id);
284	      setFicha(null);
285	      setMsg({ tipo: 'ok', texto: 'Motoboy aceito!' });
286	      setTimeout(() => setMsg(null), 3000);
287	      reload();
288	    } catch (err) {
289	      setMsg({ tipo: 'erro', texto: err.message });
290	    } finally {
291	      setProcessando(false);
292	    }
293	  };
294	
295	  const handleRecusar = async (id, motivo) => {
296	    setProcessando(true);
297	    try {
298	      await recusarSolicitacaoMotoboy(id, motivo);
299	      setFicha(null);
300	      reload();
301	    } catch (err) {
302	      setMsg({ tipo: 'erro', texto: err.message });
303	    } finally {
304	      setProcessando(false);
305	    }
306	  };
307	
308	  const handleRevisar = async (id) => {
309	    setRevisando(id);
310	    try {
311	      await revisarSolicitacaoMotoboy(id);
312	      reload();
313	    } catch (err) {
314	      setMsg({ tipo: 'erro', texto: err.message });
315	    } finally {
316	      setRevisando(null);
317	    }
318	  };
319	
320	  const handleRemover = async (mb) => {
321	    if (!window.confirm(`Remover "${mb.name}" dos seus entregadores?`)) return;
322	    setRemovendo(mb.id);
323	    try {
324	      await removerAfiliacaoMotoboy(mb.id);
325	      setMotoboys((prev) => prev.filter((m) => m.id !== mb.id));
326	    } catch (err) {
327	      setMsg({ tipo: 'erro', texto: err.message });
328	    } finally {
329	      setRemovendo(null);
330	    }
331	  };
332	
333	  const handleSalvarForm = async (dados) => {
334	    setSalvandoForm(true);
335	    setErroForm(null);
336	    try {
337	      if (formModal === 'novo') {
338	        await criarMotoboy(dados);
339	        setMsg({ tipo: 'ok', texto: 'Motoboy cadastrado!' });
340	      } else {
341	        await editarMotoboy(formModal.id, dados);
342	        setMsg({ tipo: 'ok', texto: 'Motoboy atualizado!' });
343	      }
344	      setTimeout(() => setMsg(null), 3000);
345	      setFormModal(null);
346	      reload();
347	    } catch (err) {
348	      setErroForm(err.message);
349	    } finally {
350	      setSalvandoForm(false);
351	    }
352	  };
