1	import React, { useState, useEffect, useCallback } from 'react';
2	import { getMotoboysAdmin, getMotoboyDetalheAdmin, aprovarMotoboyAdmin, recusarMotoboyAdmin } from '../../services/adminService';
3	import Icon from '../../components/AppIcon';
4	import AdminHeader from '../../components/admin/AdminHeader';
5	
6	const STATUS_LABEL = {
7	  pendente: { label: 'Pendente', cls: 'bg-amber-100 dark:bg-amber-950/40 text-amber-700 dark:text-amber-400' },
8	  aprovado: { label: 'Aprovado', cls: 'bg-green-100 dark:bg-green-950/40 text-green-700 dark:text-green-400' },
9	  recusado: { label: 'Recusado', cls: 'bg-red-100 dark:bg-red-950/40 text-red-700 dark:text-red-400' },
10	};
11	
12	const Badge = ({ status }) => {
13	  const s = STATUS_LABEL[status] ?? { label: status, cls: 'bg-gray-100 dark:bg-zinc-700 text-gray-500 dark:text-zinc-400' };
14	  return <span className={`text-xs font-semibold px-2 py-0.5 rounded-full ${s.cls}`}>{s.label}</span>;
15	};
16	
17	const Documento = ({ label, url }) => (
18	  <div>
19	    <p className="text-xs font-semibold text-gray-500 dark:text-zinc-400 mb-1">{label}</p>
20	    {url ? (
21	      <a href={url} target="_blank" rel="noreferrer" className="block border border-gray-200 dark:border-zinc-700 rounded-xl overflow-hidden hover:border-blue-400">
22	        <img src={url} alt={label} className="w-full h-32 object-cover" />
23	      </a>
24	    ) : (
25	      <div className="border border-dashed border-gray-200 dark:border-zinc-700 rounded-xl h-32 flex items-center justify-center text-xs text-gray-400 dark:text-zinc-500">
26	        Não enviado
27	      </div>
28	    )}
29	  </div>
30	);
31	
32	const DetalheModal = ({ motoboyId, onClose, onAtualizado }) => {
33	  const [mb, setMb] = useState(null);
34	  const [erro, setErro] = useState(null);
35	  const [processando, setProcessando] = useState(false);
36	  const [motivo, setMotivo] = useState('');
37	  const [mostrarRecusa, setMostrarRecusa] = useState(false);
38	
39	  const carregar = useCallback(() => {
40	    getMotoboyDetalheAdmin(motoboyId).then(setMb).catch((e) => setErro(e.message));
41	  }, [motoboyId]);
42	
43	  useEffect(() => { carregar(); }, [carregar]);
44	
45	  const handleAprovar = async () => {
46	    setProcessando(true);
47	    setErro(null);
48	    try {
49	      await aprovarMotoboyAdmin(motoboyId);
50	      onAtualizado();
51	    } catch (e) {
52	      setErro(e.message);
53	    } finally {
54	      setProcessando(false);
55	    }
56	  };
57	
58	  const handleRecusar = async () => {
59	    setProcessando(true);
60	    setErro(null);
61	    try {
62	      await recusarMotoboyAdmin(motoboyId, motivo.trim() || undefined);
63	      onAtualizado();
64	    } catch (e) {
65	      setErro(e.message);
66	    } finally {
67	      setProcessando(false);
68	    }
69	  };
70	
71	  return (
72	    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4" onClick={onClose}>
73	      <div className="bg-white dark:bg-zinc-800 rounded-2xl w-full max-w-lg p-6 max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
74	        {!mb ? (
75	          <div className="flex justify-center py-10">
76	            <div className="w-6 h-6 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
77	          </div>
78	        ) : (
79	          <>
80	            <div className="flex items-center justify-between mb-4">
81	              <div className="flex items-center gap-3">
82	                {mb.foto_perfil_url
83	                  ? <img src={mb.foto_perfil_url} alt="" className="w-12 h-12 rounded-full object-cover" />
84	                  : <div className="w-12 h-12 rounded-full bg-gray-100 dark:bg-zinc-700 flex items-center justify-center"><Icon name="User" size={20} className="text-gray-400 dark:text-zinc-500" /></div>}
85	                <div>
86	                  <h3 className="font-bold text-gray-900 dark:text-zinc-100">{mb.name}</h3>
87	                  <Badge status={mb.status_plataforma} />
88	                </div>
89	              </div>
90	              <button onClick={onClose} className="text-gray-400 dark:text-zinc-500 hover:text-gray-900 dark:hover:text-zinc-100">
91	                <Icon name="X" size={18} />
92	              </button>
93	            </div>
94	
95	            <div className="space-y-1 text-sm text-gray-600 dark:text-zinc-400 mb-4">
96	              {mb.phone && <p className="flex items-center gap-2"><Icon name="Phone" size={13} /> {mb.phone}</p>}
97	              {mb.email && <p className="flex items-center gap-2"><Icon name="Mail" size={13} /> {mb.email}</p>}
98	              {mb.revisoes_solicitadas > 0 && (
99	                <p className="flex items-center gap-2"><Icon name="RotateCcw" size={13} /> {mb.revisoes_solicitadas} pedido(s) de revisão já usado(s)</p>
100	              )}
101	            </div>
102	
103	            <div className="grid grid-cols-2 gap-3 mb-4">
104	              <Documento label="Documento (frente)" url={mb.documento_frente_url} />
105	              <Documento label="Documento (verso)" url={mb.documento_verso_url} />
106	              <Documento label="Comprovante de endereço" url={mb.comprovante_endereco_url} />
107	            </div>
108	
109	            {mb.status_plataforma === 'recusado' && mb.motivo_recusa_plataforma && (
110	              <p className="text-xs text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 rounded-lg px-3 py-2 mb-4">
111	                Motivo da recusa: {mb.motivo_recusa_plataforma}
112	              </p>
113	            )}
114	
115	            {erro && <p className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/30 rounded-lg px-3 py-2 mb-4">{erro}</p>}
116	
117	            {mostrarRecusa ? (
118	              <div className="space-y-2">
119	                <textarea value={motivo} onChange={(e) => setMotivo(e.target.value)}
120	                  placeholder="Motivo da recusa (opcional)"
121	                  rows={2}
122	                  className="w-full border border-gray-300 dark:border-zinc-700 bg-white dark:bg-zinc-900 text-gray-900 dark:text-zinc-100 rounded-xl px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-red-500" />
123	                <div className="flex gap-2">
124	                  <button onClick={() => setMostrarRecusa(false)} disabled={processando}
125	                    className="flex-1 py-2.5 border border-gray-300 dark:border-zinc-700 rounded-xl text-sm text-gray-700 dark:text-zinc-300">
126	                    Voltar
127	                  </button>
128	                  <button onClick={handleRecusar} disabled={processando}
129	                    className="flex-1 py-2.5 bg-red-600 text-white rounded-xl text-sm font-semibold hover:bg-red-700 disabled:opacity-50">
130	                    {processando ? 'Enviando...' : 'Confirmar recusa'}
131	                  </button>
132	                </div>
133	              </div>
134	            ) : (
135	              <div className="flex gap-2">
136	                <button onClick={() => setMostrarRecusa(true)} disabled={processando || mb.status_plataforma === 'recusado'}
137	                  className="flex-1 py-2.5 border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 rounded-xl text-sm font-semibold hover:bg-red-50 dark:hover:bg-red-950/40 disabled:opacity-40">
138	                  Recusar
139	                </button>
140	                <button onClick={handleAprovar} disabled={processando || mb.status_plataforma === 'aprovado'}
141	                  className="flex-1 py-2.5 bg-green-600 text-white rounded-xl text-sm font-semibold hover:bg-green-700 disabled:opacity-50">
142	                  {processando ? 'Enviando...' : 'Aprovar'}
143	                </button>
144	              </div>
145	            )}
146	          </>
147	        )}
148	      </div>
149	    </div>
150	  );
151	};
152	
153	const AdminMotoboys = () => {
154	  const [motoboys, setMotoboys] = useState([]);
155	  const [loading, setLoading] = useState(true);
156	  const [erro, setErro] = useState(null);
157	  const [filtro, setFiltro] = useState('pendente');
158	  const [detalheId, setDetalheId] = useState(null);
159	
160	  const carregar = useCallback(() => {
161	    setLoading(true);
162	    getMotoboysAdmin(filtro || undefined)
163	      .then((d) => setMotoboys(d.motoboys ?? []))
164	      .catch((e) => setErro(e.message))
165	      .finally(() => setLoading(false));
166	  }, [filtro]);
167	
168	  useEffect(() => { carregar(); }, [carregar]);
169	
170	  const FiltroBtn = ({ valor, label }) => (
171	    <button onClick={() => setFiltro(valor)}
172	      className={`px-3 py-1.5 text-xs font-semibold rounded-full transition-colors ${
173	        filtro === valor ? 'bg-blue-600 text-white' : 'bg-gray-100 dark:bg-zinc-700 text-gray-600 dark:text-zinc-300 hover:bg-gray-200 dark:hover:bg-zinc-600'
174	      }`}>
175	      {label}
176	    </button>
177	  );
178	
179	  return (
180	    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
181	      <AdminHeader active="/admin/motoboys" title="Motoboys" subtitle="Aprove cadastros antes de liberar acesso aos estabelecimentos" />
182	
183	      <main className="p-6 max-w-4xl mx-auto">
184	        <div className="flex items-center gap-2 mb-6">
185	          <FiltroBtn valor="pendente" label="Pendentes" />
186	          <FiltroBtn valor="aprovado" label="Aprovados" />
187	          <FiltroBtn valor="recusado" label="Recusados" />
188	          <FiltroBtn valor="" label="Todos" />
189	        </div>
190	
191	        {erro && <p className="text-red-600 dark:text-red-400 text-sm mb-4 bg-red-50 dark:bg-red-950/30 rounded-lg px-4 py-3">{erro}</p>}
192	
193	        {loading ? (
194	          <div className="flex justify-center py-16">
195	            <div className="w-8 h-8 border-4 border-blue-600 border-t-transparent rounded-full animate-spin" />
196	          </div>
197	        ) : motoboys.length === 0 ? (
198	          <div className="bg-white dark:bg-zinc-800 rounded-2xl border border-gray-200 dark:border-zinc-700 p-14 text-center">
199	            <Icon name="Bike" size={44} className="text-gray-200 dark:text-zinc-600 mx-auto mb-3" />
200	            <p className="text-gray-400 dark:text-zinc-500">Nenhum motoboy nesse filtro</p>
201	          </div>
202	        ) : (
203	          <div className="space-y-3">
204	            {motoboys.map((m) => (
205	              <button key={m.id} onClick={() => setDetalheId(m.id)}
206	                className="w-full text-left bg-white dark:bg-zinc-800 rounded-2xl border border-gray-100 dark:border-zinc-700 px-5 py-4 flex items-center gap-4 hover:shadow-md transition-shadow">
207	                {m.foto_perfil_url
208	                  ? <img src={m.foto_perfil_url} alt="" className="w-11 h-11 rounded-full object-cover flex-shrink-0" />
209	                  : <div className="w-11 h-11 rounded-full bg-gray-100 dark:bg-zinc-700 flex items-center justify-center flex-shrink-0"><Icon name="User" size={18} className="text-gray-400 dark:text-zinc-500" /></div>}
210	                <div className="flex-1 min-w-0">
211	                  <p className="font-bold text-gray-900 dark:text-zinc-100 truncate">{m.name}</p>
212	                  <p className="text-xs text-gray-500 dark:text-zinc-400 truncate">{m.phone || m.email || '—'}</p>
213	                </div>
214	                <Badge status={m.status_plataforma} />
215	                <Icon name="ChevronRight" size={16} className="text-gray-300 dark:text-zinc-600 flex-shrink-0" />
216	              </button>
217	            ))}
218	          </div>
219	        )}
220	      </main>
221	
222	      {detalheId && (
223	        <DetalheModal
224	          motoboyId={detalheId}
225	          onClose={() => setDetalheId(null)}
226	          onAtualizado={() => { setDetalheId(null); carregar(); }}
227	        />
228	      )}
229	    </div>
230	  );
231	};
232	
233	export default AdminMotoboys;
