648	  // Estabelecimento pode remover qualquer item (pendente ou já enviado) — diferente do
649	  // garçom, que só mexe em item ainda não enviado (ver salao.service.ts).
650	  // Estabelecimento pode editar qualquer item (pendente ou já enviado) — diferente do
651	  // garçom, que só mexe em item ainda não enviado (ver salao.service.ts).
652	  async editarItem(comandaId: number, restaurantId: number, itemId: number, body: { quantity?: number; observacao?: string }) {
653	    const comanda = await this.buscarComanda(comandaId, restaurantId);
654	    // Venda balcão só envia os itens pra cozinha/bar depois de paga (ver `adicionarItens`/
655	    // `pagar`) — quando o item chega na Produção a comanda já está com status 'paga', então
656	    // precisa liberar edição de observação mesmo paga (só pra venda balcão; quantidade
657	    // continua travada, já foi cobrada).
658	    const podeEditar = ['aberta', 'fechada_garcom'].includes(comanda.status)
659	      || (comanda.is_venda_balcao && comanda.status === 'paga');
660	    if (!podeEditar) {
661	      throw new BadRequestException('Comanda já foi paga ou cancelada');
662	    }
663	    if (comanda.status === 'paga' && body.quantity !== undefined) {
664	      throw new BadRequestException('Não é possível alterar quantidade de uma venda já finalizada');
665	    }
666	
667	    const { data: item } = await this.supabase.client
668	      .from('order_items').select('id, product_id, quantity').eq('id', itemId).eq('order_id', comandaId).maybeSingle();
669	    if (!item) throw new NotFoundException('Item não encontrado');
670	
671	    const update: Record<string, unknown> = {};
672	    if (body.quantity !== undefined) {
673	      if (body.quantity < 1) throw new BadRequestException('Quantidade mínima é 1');
674	      update.quantity = body.quantity;
675	    }
676	    if (body.observacao !== undefined) update.observacao = body.observacao?.trim() || null;
677	
678	    const { error } = await this.supabase.client.from('order_items').update(update).eq('id', itemId);
679	    if (error) throw error;
680	
681	    if (body.quantity !== undefined && body.quantity !== item.quantity) {
682	      await this.estoque.ajustarPorDelta(item.product_id, item.quantity, body.quantity);
683	    }
684	
685	    if (comanda.status !== 'paga') {
