1	import { BadRequestException, Injectable, NotFoundException } from '@nestjs/common';
2	import * as crypto from 'crypto';
3	import * as bcrypt from 'bcryptjs';
4	import { SupabaseService } from '../supabase/supabase.service';
5	
6	export interface CriarGarcomBody {
7	  nome: string;
8	  telefone?: string;
9	  senha: string;
10	  permissoes?: { pagamento_parcial?: boolean };
11	}
12	
13	export interface AtualizarGarcomBody {
14	  nome?: string;
15	  telefone?: string;
16	  ativo?: boolean;
17	  senha?: string;
18	  permissoes?: { pagamento_parcial?: boolean };
19	}
20	
21	export interface ComissaoConfigBody {
22	  nome: string;
23	  tipo: 'percentual' | 'fixo';
24	  valor: number;
25	  base_calculo?: 'total_vendido' | 'total_recebido';
26	  ativo?: boolean;
27	}
28	
29	@Injectable()
30	export class GarconsService {
31	  constructor(private supabase: SupabaseService) {}
32	
33	  private gerarLoginKey(): string {
34	    return crypto.randomBytes(4).toString('hex');
35	  }
36	
37	  async criar(restaurantId: number, body: CriarGarcomBody) {
38	    if (!body.nome) throw new BadRequestException('Nome é obrigatório');
39	    if (!body.senha || body.senha.length < 8) throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
40	
41	    const passwordHash = await bcrypt.hash(body.senha, 10);
42	    let loginKey = this.gerarLoginKey();
43	
44	    for (let tentativas = 0; tentativas < 5; tentativas++) {
45	      const { data: existente } = await this.supabase.client
46	        .from('garcons')
47	        .select('id')
48	        .eq('login_key', loginKey)
49	        .maybeSingle();
50	      if (!existente) break;
51	      loginKey = this.gerarLoginKey();
52	    }
53	
54	    const { data, error } = await this.supabase.client
55	      .from('garcons')
56	      .insert({
57	        restaurant_id: restaurantId,
58	        nome: body.nome,
59	        telefone: body.telefone ?? null,
60	        login_key: loginKey,
61	        password_hash: passwordHash,
62	        permissoes: {
63	          // Default true — pagamento parcial já era permitido sem restrição antes dessa
64	          // permissão existir, então continua liberado por padrão.
65	          pagamento_parcial: body.permissoes?.pagamento_parcial !== false,
66	        },
67	      })
68	      .select('id, nome, telefone, login_key, ativo, permissoes, created_at')
69	      .single();
70	    if (error) throw error;
71	
72	    return data;
73	  }
74	
75	  async listar(restaurantId: number) {
76	    const { data, error } = await this.supabase.client
77	      .from('garcons')
78	      .select('id, nome, telefone, login_key, ativo, permissoes, ultimo_acesso_em, active_session_id, session_expires_at, bloqueado_ate, created_at')
79	      .eq('restaurant_id', restaurantId)
80	      .order('created_at', { ascending: false });
81	    if (error) throw error;
82	
83	    const agora = Date.now();
84	    return (data ?? []).map(({ active_session_id, session_expires_at, bloqueado_ate, ...resto }) => ({
85	      ...resto,
86	      sessao_ativa: !!active_session_id && !!session_expires_at && new Date(session_expires_at).getTime() > agora,
87	      bloqueado_ate: bloqueado_ate && new Date(bloqueado_ate).getTime() > agora ? bloqueado_ate : null,
88	    }));
89	  }
90	
91	  private async garantirPertence(id: number, restaurantId: number) {
92	    const { data } = await this.supabase.client
93	      .from('garcons')
94	      .select('id')
95	      .eq('id', id)
96	      .eq('restaurant_id', restaurantId)
97	      .maybeSingle();
98	    if (!data) throw new NotFoundException('Garçom não encontrado');
99	  }
100	
101	  async atualizar(id: number, restaurantId: number, body: AtualizarGarcomBody) {
102	    await this.garantirPertence(id, restaurantId);
103	
104	    const update: Record<string, unknown> = {};
105	    if (body.nome !== undefined) update.nome = body.nome;
106	    if (body.telefone !== undefined) update.telefone = body.telefone;
107	    if (body.ativo !== undefined) update.ativo = body.ativo;
108	    if (body.permissoes !== undefined) {
109	      update.permissoes = {
110	        pagamento_parcial: body.permissoes.pagamento_parcial !== false,
111	      };
112	    }
113	    if (body.senha) {
114	      if (body.senha.length < 8) throw new BadRequestException('Senha deve ter no mínimo 8 caracteres');
115	      update.password_hash = await bcrypt.hash(body.senha, 10);
116	    }
117	
118	    const { data, error } = await this.supabase.client
119	      .from('garcons')
120	      .update(update)
121	      .eq('id', id)
122	      .select('id, nome, telefone, login_key, ativo, permissoes, created_at')
123	      .single();
124	    if (error) throw error;
125	
126	    return data;
127	  }
128	
129	  async remover(id: number, restaurantId: number) {
130	    await this.garantirPertence(id, restaurantId);
131	    const { error } = await this.supabase.client.from('garcons').delete().eq('id', id);
132	    if (error) throw error;
133	    return { ok: true };
134	  }
135	
136	  // Libera o garçom pra logar em outro dispositivo, encerrando a sessão travada.
137	  async forcarLogout(id: number, restaurantId: number) {
138	    await this.garantirPertence(id, restaurantId);
139	    const { error } = await this.supabase.client
140	      .from('garcons')
141	      .update({ active_session_id: null, session_expires_at: null })
142	      .eq('id', id);
143	    if (error) throw error;
144	    return { ok: true };
145	  }
146	
147	  // Libera na hora o bloqueio por senha errada repetida (ver MAX_TENTATIVAS_LOGIN em
148	  // garcom-auth.service.ts) — ação separada de forcarLogout: ali o garçom está logado
149	  // em outro lugar, aqui ele não consegue nem entrar em lugar nenhum.
150	  async liberarBloqueio(id: number, restaurantId: number) {
151	    await this.garantirPertence(id, restaurantId);
152	    const { error } = await this.supabase.client
153	      .from('garcons')
154	      .update({ tentativas_login_falhas: 0, bloqueado_ate: null })
155	      .eq('id', id);
156	    if (error) throw error;
157	    return { ok: true };
158	  }
159	
160	  async garconsOnline(restaurantId: number) {
161	    const limite = new Date(Date.now() - 5 * 60 * 1000).toISOString();
162	    const { data, error } = await this.supabase.client
163	      .from('garcons')
164	      .select('id, nome, ultimo_acesso_em')
165	      .eq('restaurant_id', restaurantId)
166	      .eq('ativo', true)
167	      .gte('ultimo_acesso_em', limite);
168	    if (error) throw error;
169	    return data;
170	  }
